/**
 * Ensure the submission request satisfies certain requirements. If executor spec is present in
 * request, the number of executors shouldn't exceed the limit. If executor spec is present as
 * `spark.executor.instances` param in Spark conf, the number of executors shouldn't exceed the
 * limit.
 *
 * @param request submission request
 * @param queueName name of the queue
 */
private void validateSubmissionRequest(SubmitApplicationRequest request, String queueName) {
    int maxExecutorInstances = getMaxExecutorInstanceForQueue(queueName);
    if (request.getExecutor() != null) {
        Integer instances = request.getExecutor().getInstances();
        if (instances != null) {
            if (instances > maxExecutorInstances) {
                throw new WebApplicationException(String.format("Executor instances in Spark config (%s) exceeds limit (%d)", instances, maxExecutorInstances), Response.Status.BAD_REQUEST);
            }
        }
    }
    if (request.getSparkConf() != null) {
        String configValueStr = request.getSparkConf().get(SparkConstants.SPARK_CONF_EXECUTOR_INSTANCES);
        if (configValueStr != null) {
            int instances;
            try {
                instances = Integer.parseInt(configValueStr);
            } catch (Throwable ex) {
                throw new WebApplicationException(String.format("Invalid value (%s) for Spark config: (%s)", configValueStr, SparkConstants.SPARK_CONF_EXECUTOR_INSTANCES), Response.Status.BAD_REQUEST);
            }
            if (instances > maxExecutorInstances) {
                throw new WebApplicationException(String.format("Executor instances in Spark config (%s) exceeds limit (%d)", instances, maxExecutorInstances), Response.Status.BAD_REQUEST);
            }
        }
    }
}
